sysevent_script_action.script:
// Queue up the import of this new file.
queueNewImport(event.parm1 /* Sys_id of newly arrived file */ );

function queueNewImport(attachmentSysId) {
    // Queue the file up for import via data source "Vendor Data", unless...
    const app_id = "52739d78c35b7290c134bf12b4013100"; // "Import Visibility"

    const ds_vendor_data_queue_sys_id = getDataSourceSysId(app_id, "Vendor Data Queue");
    const ds_vendor_data_sys_id = getDataSourceSysId(app_id, "Vendor Data");
    const ds_vendor_data_archive_sys_id = getDataSourceSysId(app_id, "Vendor Data Archive");

    const vendorDataUtils = new VendorDataUtils();

    if (!ds_vendor_data_queue_sys_id) {
        throw ("Data Source 'Vendor Data Queue' not found.");
    }
    if (!ds_vendor_data_sys_id) {
        throw ("Data Source 'Vendor Data' not found.");
    }
    if (!ds_vendor_data_archive_sys_id) {
        throw ("Data Source 'Vendor Data Archive' not found.");
    }

    // Run a subflow to ingest this file, unless there is already
    // an import queued up for a different file. That might happen
    // if several files arrive at abot the same time.

    try {
        var inputs = {};
        inputs['application_id'] = app_id;
        inputs['vendor_data_queue_sysid'] = ds_vendor_data_queue_sys_id;
        inputs['vendor_data_sysid'] = ds_vendor_data_sys_id;
        inputs['vendor_data_archive_sysid'] = ds_vendor_data_archive_sys_id;
        inputs['attachment_sysid'] = attachmentSysId;

        // Start Asynchronously: Uncomment to run in background. Code snippet will not have access to outputs.
        // sn_fd.FlowAPI.getRunner().subflow('x_42999_import_v_0.import_vendor_data').inBackground().withInputs(inputs).run();

        // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
        var result = sn_fd.FlowAPI
            .getRunner()
            .subflow('x_42999_import_v_0.import_vendor_data')
            .inForeground()
            .withInputs(inputs)
            .run();
        var outputs = result.getOutputs();
        var output = outputs['output']; // JSON
        gs.info(JSON.stringify(output));
    } catch (ex) {
        var message = ex.getMessage();
        gs.error(message);
    }
}

function getDataSourceSysId(app_id, name) {
    var result = null;
    var gr = new GlideRecord("sys_data_source");
    gr.addQuery("sys_scope", app_id);
    gr.addQuery("name", name);
    gr.setLimit(1);
    gr.query();
    if (gr.next()) result = gr.getValue("sys_id");
    return result;
}

